# Cyrillic transforms without accidentally altering russian explanatory labels.
MAP={'lj':'љ','nj':'њ','dž':'џ','a':'а','b':'б','c':'ц','č':'ч','ć':'ћ','d':'д','đ':'ђ','e':'е','f':'ф','g':'г','h':'х','i':'и','j':'ј','k':'к','l':'л','m':'м','n':'н','o':'о','p':'п','r':'р','s':'с','š':'ш','t':'т','u':'у','v':'в','z':'з','ž':'ж'}
def to_cyr(s):
 result='';i=0
 while i<len(s):
  pair=s[i:i+2].lower()
  key=pair if pair in ('lj','nj','dž') else s[i].lower()
  val=MAP.get(key,s[i])
  if s[i].isupper():val=val.upper()
  result+=val;i+=len(key)
 return result
